-- BACKUP: bak_20261026_v_cost_forecast
-- Rollback: UPDATE spof_alternate_probes SET probe_sql = (SELECT h.probe_sql FROM spof_alternate_probes h WHERE h.component = spof_alternate_probes.component || '@before-calibration-1'), window_note = (SELECT h.window_note FROM spof_alternate_probes h WHERE h.component = spof_alternate_probes.component || '@before-calibration-1') WHERE component = 'remediation reopen on relapse' AND EXISTS (SELECT 1 FROM spof_alternate_probes h WHERE h.component = spof_alternate_probes.component || '@before-calibration-1'); UPDATE control_alternate_probes SET probe_sql = (SELECT h.probe_sql FROM control_alternate_probes h WHERE h.control = control_alternate_probes.control || '@before-calibration-1'), window_note = (SELECT h.window_note FROM control_alternate_probes h WHERE h.control = control_alternate_probes.control || '@before-calibration-1') WHERE control IN ('agent-ws-reactivation-prerequisites', 'compat-advance-review-gate') AND EXISTS (SELECT 1 FROM control_alternate_probes h WHERE h.control = control_alternate_probes.control || '@before-calibration-1'); UPDATE ops_config SET value = '360000', note = substr(note, instr(note, char(10)) + 1) WHERE key = 'research_daily_neurons' AND value = '310000' AND note LIKE 'COST-BOUND-RESTORE-1%'; UPDATE ops_config SET value = '150000', note = substr(note, instr(note, char(10)) + 1) WHERE key = 'q08_daily_neurons' AND value = '100000' AND note LIKE 'COST-BOUND-RESTORE-1%'; DROP VIEW IF EXISTS v_cost_forecast; CREATE VIEW v_cost_forecast AS WITH b AS ( SELECT date('now', 'start of month') AS m0, date('now') AS d0, CAST(julianday(date('now', 'start of month', '+1 month')) - julianday(date('now', 'start of month')) AS INTEGER) AS dim, CAST(julianday(date('now')) - julianday(date('now', 'start of month')) AS INTEGER) AS done ), c AS ( SELECT date, usd, CASE WHEN source = 'workers_ai' OR instr(source, 'ai_gateway:') = 1 OR source = 'cloudflare_plan:daily' THEN 'fleet' WHEN instr(source, 'owner_gateway:') = 1 THEN 'owner_clients' WHEN source = 'direct_providers_external:daily' THEN 'owner_direct_unverified' END AS scope FROM cost_daily WHERE date >= date('now', '-40 days') ), g AS ( SELECT c.scope, SUM(CASE WHEN c.date >= b.m0 AND c.date < b.d0 THEN c.usd ELSE 0 END) AS mtd, SUM(CASE WHEN c.date = b.d0 THEN c.usd ELSE 0 END) AS today, SUM(CASE WHEN c.date >= date('now', '-3 days') AND c.date < b.d0 THEN c.usd ELSE 0 END) / 3.0 AS d3, SUM(CASE WHEN c.date >= date('now', '-7 days') AND c.date < b.d0 THEN c.usd ELSE 0 END) / 7.0 AS d7, MAX(b.dim) AS dim, MAX(b.done) AS done FROM c, b WHERE c.scope IS NOT NULL GROUP BY c.scope ) SELECT scope, ROUND(mtd, 2) AS mtd_complete_usd, ROUND(today, 2) AS today_partial_usd, ROUND(d3, 4) AS daily_3d, ROUND(d7, 4) AS daily_7d, ROUND(d3 * 30, 2) AS pace_30d_usd, ROUND(mtd + (dim - done) * d3, 2) AS forecast_month_usd, dim AS days_in_month, done AS complete_days, CASE WHEN scope = 'fleet' THEN 300 END AS budget_month_usd, CASE scope WHEN 'fleet' THEN 'measured: GraphQL Workers AI neurons + AI Gateway fleet cost + Cloudflare subscriptions' WHEN 'owner_clients' THEN 'measured: owner desktop clients on the gateway (ai_spend_owner_local)' ELSE 'UNVERIFIED owner-stated monthly figure / 30; no API sees it' END AS basis FROM g; DELETE FROM remediation_contracts WHERE class = 'fm-cost-forecast-view-clobbered'; DELETE FROM failure_modes WHERE fm_key = 'cost-forecast-view-clobbered'
-- spof-review: no cron, trigger, binding, host or credential; three probe rows edited, one view recreated, two ops_config caps, one failure mode and its detector contract.

INSERT OR IGNORE INTO spof_alternate_probes (component, probe_sql, exercise, window_note, enabled)
SELECT component || '@before-calibration-1', probe_sql, exercise, COALESCE(window_note, ''), 0 FROM spof_alternate_probes
WHERE component = 'remediation reopen on relapse' AND instr(probe_sql, 'no recurrence_guard_actions row in 7 days') > 0;

UPDATE spof_alternate_probes SET probe_sql = 'SELECT ''ok'' AS expected, CASE WHEN NOT EXISTS (SELECT 1 FROM sqlite_master WHERE type = ''trigger'' AND name = ''recurrence_guard_tick'' AND tbl_name = ''fleet_tick'' AND instr(sql, ''INSERT INTO recurrence_guard_actions'') > 0 AND instr(sql, ''SET status = ''''open'''''') > 0) THEN ''the recurrence_guard_tick trigger is gone or no longer reopens a closed issue'' WHEN COALESCE((SELECT value FROM ops_config WHERE key = ''queue_sla_autofix''), ''on'') = ''off'' THEN ''ops_config queue_sla_autofix is off, so recurrence_guard_tick does not act'' WHEN (SELECT COUNT(*) FROM fleet_tick WHERE ts > strftime(''%Y-%m-%dT%H:%M:%SZ'', ''now'', ''-3 hours'') AND CAST(strftime(''%M'', ts) AS INTEGER) < 10) = 0 THEN ''no fleet_tick insert in minutes 0 to 9 in 3 hours, so the gate of recurrence_guard_tick never opens'' WHEN EXISTS (SELECT 1 FROM (SELECT c.max_attempts, (SELECT COUNT(*) FROM remediation_verifications v WHERE v.class = c.class AND v.pass = 0 AND COALESCE(v.observed, '''') <> '''' AND lower(trim(v.observed)) NOT LIKE ''pending%'' AND v.verified_at < datetime(''now'', ''-75 minutes'') AND v.verified_at > MAX(COALESCE((SELECT replace(substr(MAX(l.ts), 1, 19), ''T'', '' '') FROM issue_lifecycle l WHERE l.issue_id = a.id AND l.event IN (''dispositioned'', ''closed'') AND l.to_status IN (''closed'', ''resolved'')), datetime(a.updated_at / 1000, ''unixepoch'')), COALESCE((SELECT MAX(p.verified_at) FROM remediation_verifications p WHERE p.class = c.class AND p.pass = 1), ''1970-01-01''))) AS fails, (SELECT substr(v.observed, 1, 120) FROM remediation_verifications v WHERE v.class = c.class ORDER BY v.verified_at DESC LIMIT 1) AS last_observed FROM remediation_contracts c JOIN agent_issues a ON a.id = c.issue_id WHERE c.status IN (''active'', ''holding'') AND a.status IN (''closed'', ''resolved'') AND typeof(a.updated_at) = ''integer'' AND a.updated_at < (CAST(strftime(''%s'', ''now'') AS INTEGER) - 7200) * 1000 AND NOT EXISTS (SELECT 1 FROM agent_issues o WHERE o.status = ''open'' AND o.id <> a.id AND lower(trim(o.title)) = lower(trim(a.title)))) x WHERE x.fails >= MAX(1, COALESCE(x.max_attempts, 3)) AND COALESCE(x.last_observed, '''') <> '''' AND lower(trim(x.last_observed)) NOT LIKE ''pending%'') THEN ''a closed issue failed its contract past max_attempts for over 75 minutes and was not reopened'' ELSE ''ok'' END AS observed', window_note = 'state probe, armed-and-unneeded (SWEEP-PROBE-FIXES-B-1, like CHAOS-DRILL-TICK-ALT-1): the D1 reopen path acts only when a closure relapses and the drill does not manufacture a relapse, so it no longer demands an action row in 7 days. It reads the control: the recurrence_guard_tick trigger exists and still reopens, ops_config queue_sla_autofix is not off, a fleet_tick insert landed in minutes 0 to 9 in the last 3 hours (the trigger gate), and no closed issue without an open twin has failed its contract max_attempts times for over 75 minutes (the trigger relapse select) and stayed closed. Evidence of a real reopen is not required, and recurrence_guard_actions rows do not excuse a broken trigger'
WHERE component = 'remediation reopen on relapse' AND instr(probe_sql, 'no recurrence_guard_actions row in 7 days') > 0 AND instr(probe_sql, 'recurrence_guard_tick') = 0;

INSERT OR IGNORE INTO control_alternate_probes (control, probe_sql, window_note, enabled)
SELECT control || '@before-calibration-1', probe_sql, COALESCE(window_note, ''), 0 FROM control_alternate_probes
WHERE (control = 'agent-ws-reactivation-prerequisites' AND instr(probe_sql, 'code-task: repo=qnfo-workers path=qnfo-agent-ws/worker.js') > 0)
   OR (control = 'compat-advance-review-gate' AND instr(probe_sql, 'no ok compat-verify event in 7 days') > 0);

UPDATE control_alternate_probes SET probe_sql = 'SELECT ''ok'' AS expected, CASE WHEN NOT EXISTS (SELECT 1 FROM agent_issues a JOIN control_registry c ON c.control = ''agent-ws-reactivation-prerequisites'' AND c.disposition = ''keep'' AND c.disposition_state = ''applied'' WHERE a.title = ''AGENT-WS-REACTIVATION-1: resolve the consumer and fleet-cap prerequisites before reactivating qnfo-agent-ws'' AND a.status = ''open'') THEN ''the open AGENT-WS-REACTIVATION-1 issue or the keep disposition is missing'' WHEN NOT EXISTS (SELECT 1 FROM agent_issues a JOIN remediation_contracts r ON r.issue_id = a.id WHERE a.title = ''AGENT-WS-REACTIVATION-1: resolve the consumer and fleet-cap prerequisites before reactivating qnfo-agent-ws'' AND a.status = ''open'' AND r.status IN (''active'', ''holding'', ''monitoring'', ''escalated'') AND r.verify_transport = ''runner-https'' AND instr(r.verify_probe, ''qnfo-agent-ws.q08.workers.dev/health'') > 0 AND instr(r.verify_probe, ''min_version'') > 0) THEN ''the CI-applied versioned health contract of the issue is not live'' ELSE ''ok'' END AS observed', window_note = 'SWEEP-PROBE-FIXES-B-1: read-only D1 probe on the handoff itself, the open AGENT-WS-REACTIVATION-1 issue (found by title, with the control keep and applied) and its CI-applied remediation contract (runner-https, the qnfo-agent-ws health URL, a min_version, a status that is not closed or superseded). It no longer reads the issue description: qnfo-code-orchestrator NEEDS-ANCHOR-ROUTE-1 rewrote the code-task line to session-task on 2026-10-25T18:53Z because no code task can place an edit in the 2.4 MB worker bundle, and the contract, not that line, is what the runner executes. It does not make the unavailable worker appear healthy or bypass the consumer, dependency or worker-cap prerequisites. When issue 1000140 closes, the control row takes its next disposition in the same change or this drill fails again'
WHERE control = 'agent-ws-reactivation-prerequisites' AND instr(probe_sql, 'code-task: repo=qnfo-workers path=qnfo-agent-ws/worker.js') > 0;

UPDATE control_alternate_probes SET probe_sql = 'SELECT ''ok'' AS expected, CASE WHEN NOT EXISTS (SELECT 1 FROM deployment_history WHERE action = ''deploy'' AND status = ''success'' AND deployed_at > strftime(''%Y-%m-%dT%H:%M:%SZ'', ''now'', ''-24 hours'')) THEN ''no successful deploy in 24 h, so the gate may be withholding more than the date change'' WHEN EXISTS (SELECT 1 FROM deployment_history p WHERE p.action = ''deploy'' AND p.status = ''success'' AND instr(p.notes, '' compat_date='') > 0 AND instr(p.notes, '' pending_verify'') > 0 AND p.deployed_at < strftime(''%Y-%m-%dT%H:%M:%SZ'', ''now'', ''-2 hours'') AND NOT EXISTS (SELECT 1 FROM deployment_history s WHERE s.resource_name = p.resource_name AND s.action IN (''compat-verify'', ''compat-restore'') AND s.id > p.id)) THEN ''a compat advance has waited over 2 h for its verification and neither compat-verify nor compat-restore settled it'' WHEN COALESCE((SELECT MAX(checked_at) FROM worker_compat_state), '''') < strftime(''%Y-%m-%dT%H:%M:%SZ'', ''now'', ''-24 hours'') THEN ''the compat exposure snapshot is older than 24 h, so qnfo-ops is not measuring which advances wait'' WHEN EXISTS (SELECT 1 FROM worker_compat_state WHERE checked_at = (SELECT MAX(checked_at) FROM worker_compat_state) AND instr(advance, ''next deploy advances'') = 1) AND NOT EXISTS (SELECT 1 FROM cloud_ops_events WHERE kind = ''compat-verify'' AND status = ''ok'' AND ts > strftime(''%Y-%m-%dT%H:%M:%SZ'', ''now'', ''-35 days'')) THEN ''a reviewed compat advance waits for its next deploy and no ok compat-verify event exists in 35 days'' ELSE ''ok'' END AS observed', window_note = 'SWEEP-PROBE-FIXES-B-1: 24 h for deploys (the gate withholds only the date, never the upload) and 2 h for a pending advance (an advance is recorded as pending_verify on its deploy row and settled by a later compat-verify or compat-restore of the same worker, as qnfo-ops compatPendingRow reads it). The compat verifier writes an event only when a reviewed date actually advances (3 events in 13 days, the last 2026-10-19T05:34Z, and workers_compat_date_behind is 0 with every worker declaring its live date), so absence of an event is no failure while no advance waits: the 35 day demand for an ok compat-verify event applies only while the newest exposure snapshot (24 h) shows an advance that waits for its next deploy. qnfo-ops/compat-date-apply.test.mjs still pins the gate branches'
WHERE control = 'compat-advance-review-gate' AND instr(probe_sql, 'no ok compat-verify event in 7 days') > 0;

UPDATE ops_config SET value = '310000', note = 'COST-BOUND-RESTORE-1 2026-10-26 (SWEEP-PROBE-FIXES-B-1): 360000 -> 310000. The cap-aware bound (v_cost_forecast.bound_30d_usd, restored by this change) read USD 329.21 per 30 days at the 2026-10-26 caps (852,612 neurons a day: research 360000, q08 150000, code loop 140 calls x 1787, uncapped remainder 92,427) against the owner budget of USD 300 all-in, quality not to drop. The trigger lever is to lower the largest cap. Research spent 366k to 473k a day against 360k, so the cap binds: the cut is shared with q08_daily_neurons (150000 -> 100000), 50k neurons a day each, which gives USD 296.2 and leaves room for the uncapped remainder to move. Pacing only: work over the pace waits for the next tick, no gate changes. Revert: UPDATE ops_config SET value = ''360000'' WHERE key = ''research_daily_neurons'' and read v_cost_forecast.bound_30d_usd first, it must stay at or under 300' || char(10) || COALESCE(note, ''), updated_at = datetime('now')
WHERE key = 'research_daily_neurons' AND value = '360000';

UPDATE ops_config SET value = '100000', note = 'COST-BOUND-RESTORE-1 2026-10-26 (SWEEP-PROBE-FIXES-B-1): 150000 -> 100000, the other half of the 100k neurons a day that brings the cap-aware bound from USD 329.21 to 296.2 per 30 days (see research_daily_neurons). q08-signal-engine spent 150k a day on 364 to 429 model calls for at most q08_max_per_day (10) essays, so it is the engine that can give up budget without a gate change. Pacing only. Revert: UPDATE ops_config SET value = ''150000'' WHERE key = ''q08_daily_neurons'' and read v_cost_forecast.bound_30d_usd first, it must stay at or under 300' || char(10) || COALESCE(note, ''), updated_at = datetime('now')
WHERE key = 'q08_daily_neurons' AND value = '150000';

CREATE TABLE IF NOT EXISTS bak_20261026_v_cost_forecast AS SELECT name, sql FROM sqlite_master WHERE name = 'v_cost_forecast';

DROP VIEW IF EXISTS v_cost_forecast;

CREATE VIEW v_cost_forecast AS
WITH b AS (
  SELECT date('now', 'start of month') AS m0, date('now') AS d0,
    CAST(julianday(date('now', 'start of month', '+1 month')) - julianday(date('now', 'start of month')) AS INTEGER) AS dim,
    CAST(julianday(date('now')) - julianday(date('now', 'start of month')) AS INTEGER) AS done
), cfg AS (
  SELECT
    COALESCE((SELECT CAST(value AS REAL) FROM ops_config WHERE key = 'research_daily_neurons'), 360000) AS research_n,
    COALESCE((SELECT CAST(value AS REAL) FROM ops_config WHERE key = 'q08_daily_neurons'), 150000) AS q08_n,
    COALESCE((SELECT CAST(value AS REAL) FROM ops_config WHERE key = 'code_loop_daily_calls'), 1500) AS code_calls
), meas AS (
  SELECT
    COALESCE((SELECT SUM(neurons) * 1.0 / NULLIF(SUM(calls), 0) FROM ai_call_counters WHERE worker = 'qnfo-code-orchestrator' AND day >= date('now', '-7 days') AND day < date('now')), 2000) AS code_npc,
    COALESCE((SELECT SUM(neurons) / 7.0 FROM ai_call_counters WHERE worker NOT IN ('qnfo-research-exec', 'errata-hub', 'qnfo-paper-reviser', 'q08-signal-engine', 'qnfo-code-orchestrator') AND day >= date('now', '-7 days') AND day < date('now')), 0) AS other_n
), c AS (
  SELECT date, usd,
    CASE WHEN source = 'workers_ai' OR instr(source, 'ai_gateway:') = 1 OR source = 'cloudflare_plan:daily' THEN 'fleet'
         WHEN instr(source, 'owner_gateway:') = 1 THEN 'owner_clients'
         WHEN source = 'direct_providers_external:daily' THEN 'owner_direct_unverified' END AS scope,
    CASE WHEN source = 'workers_ai' THEN 0 ELSE 1 END AS non_neuron
  FROM cost_daily WHERE date >= date('now', '-40 days')
), g AS (
  SELECT c.scope,
    SUM(CASE WHEN c.date >= b.m0 AND c.date < b.d0 THEN c.usd ELSE 0 END) AS mtd,
    SUM(CASE WHEN c.date = b.d0 THEN c.usd ELSE 0 END) AS today,
    SUM(CASE WHEN c.date >= date('now', '-3 days') AND c.date < b.d0 THEN c.usd ELSE 0 END) / 3.0 AS d3,
    SUM(CASE WHEN c.date >= date('now', '-7 days') AND c.date < b.d0 THEN c.usd ELSE 0 END) / 7.0 AS d7,
    SUM(CASE WHEN c.non_neuron = 1 AND c.date >= date('now', '-3 days') AND c.date < b.d0 THEN c.usd ELSE 0 END) / 3.0 AS d3_non_neuron,
    MAX(b.dim) AS dim, MAX(b.done) AS done
  FROM c, b WHERE c.scope IS NOT NULL GROUP BY c.scope
), bound AS (
  SELECT MAX(0, cfg.research_n + cfg.q08_n + cfg.code_calls * meas.code_npc + meas.other_n - 10000) * 0.011 / 1000 AS neuron_usd,
    cfg.research_n + cfg.q08_n + cfg.code_calls * meas.code_npc + meas.other_n AS neurons
  FROM cfg, meas
)
SELECT g.scope, ROUND(g.mtd, 2) AS mtd_complete_usd, ROUND(g.today, 2) AS today_partial_usd, ROUND(g.d3, 4) AS daily_3d, ROUND(g.d7, 4) AS daily_7d,
  ROUND(g.d3 * 30, 2) AS pace_30d_usd, ROUND(g.mtd + (g.dim - g.done) * g.d3, 2) AS forecast_month_usd, g.dim AS days_in_month, g.done AS complete_days,
  CASE WHEN g.scope = 'fleet' THEN 300 END AS budget_month_usd,
  CASE g.scope WHEN 'fleet' THEN 'measured: GraphQL Workers AI neurons + AI Gateway fleet cost + Cloudflare subscriptions'
             WHEN 'owner_clients' THEN 'measured: owner desktop clients on the gateway (ai_spend_owner_local)'
             ELSE 'UNVERIFIED owner-stated monthly figure / 30; no API sees it' END AS basis,
  CASE WHEN g.scope = 'fleet' THEN ROUND(bound.neuron_usd + g.d3_non_neuron, 4) END AS bound_daily_usd,
  CASE WHEN g.scope = 'fleet' THEN ROUND(bound.neurons) END AS bound_daily_neurons,
  CASE WHEN g.scope = 'fleet' THEN ROUND(g.mtd + (g.dim - g.done) * MIN(g.d3, bound.neuron_usd + g.d3_non_neuron), 2) ELSE ROUND(g.mtd + (g.dim - g.done) * g.d3, 2) END AS forecast_bounded_month_usd,
  CASE WHEN g.scope = 'fleet' THEN ROUND(30 * (bound.neuron_usd + g.d3_non_neuron), 2) END AS bound_30d_usd
FROM g, bound;

UPDATE metric_registry SET last_value = CAST((SELECT bound_30d_usd FROM v_cost_forecast WHERE scope = 'fleet') AS TEXT), last_refreshed = strftime('%Y-%m-%dT%H:%M:%SZ', 'now'), state = 'MEASURED'
WHERE metric = 'fleet_cost_bound_month_usd' AND (SELECT bound_30d_usd FROM v_cost_forecast WHERE scope = 'fleet') IS NOT NULL;

INSERT OR IGNORE INTO failure_modes (fm_key, failure_mode, root_cause, remediation, detector, probe_class, first_seen, issue_id, trigger_condition, symptom, blast_radius) VALUES
 ('cost-forecast-view-clobbered', 'a re-applied migration replaces the bounded v_cost_forecast with an older view and the cap-aware cost bound metric freezes without a signal',
  'migrations/2026-10-21-cost-sustain-forecast.sql ends in DROP VIEW and CREATE VIEW of the 11-column COST-SUSTAIN-1 view and upserts the ops_config caps, and the runner applies a file again whenever its sha256 changes (migration_runs 518, 2026-10-24T09:45:39Z, after migration_runs 515 had created the 15-column bounded view): the bounded view was replaced, scripts/cost_ledger.py write_forecast writes the bound only when f.get("bound_30d_usd") is not None, so fleet_cost_bound_month_usd froze at 352.76 (2026-10-25T08:45:00Z) while its sibling metrics kept refreshing and the dashboard cost feed lost fleet_bound_30d_usd',
  'SWEEP-PROBE-FIXES-B-1 recreated the bounded view (identical to migrations/2026-10-21-cost-sustain-3-bounded-forecast.sql) after a backup and wrote the metric from it. Do not edit migrations/2026-10-21-cost-sustain-forecast.sql or migrations/2026-10-21-cost-sustain-3-bounded-forecast.sql (an edit re-applies the whole file): a change to v_cost_forecast is a new file that creates the full view with every column. The detector reads the view text and the bound metric against its sibling',
  'v_cost_forecast carries bound_30d_usd and fleet_cost_bound_month_usd is not older than fleet_cost_pace_30d_usd by more than 180 minutes', 'fm-cost-forecast-view-clobbered', '2026-10-26', 1000155,
  'a migration that drops or recreates v_cost_forecast without the COST-SUSTAIN-3 columns', 'fleet_cost_bound_month_usd stops refreshing while fleet_cost_pace_30d_usd and fleet_cost_forecast_month_usd keep moving, the trigger on it can never recover and its issue stays open',
  'the owner cost bound check, the dashboard cost feed fields fleet_bound_30d_usd and fleet_forecast_bounded_month_usd');

INSERT OR IGNORE INTO remediation_contracts (class, issue_id, precondition, action, verify_probe, verify_transport, max_attempts, escalate_to, expected_cadence_h, status, module, budget_ms, max_items, requires_container) VALUES
